INSERT OR REPLACE INTO recipes (id, category, title, data_json) VALUES ('french-toast-honey-cinnamon-banana-with-chocolate', 'food', 'French Toast Honey Cinnamon Banana with Chocolate', '{"id":"french-toast-honey-cinnamon-banana-with-chocolate","name":"French Toast Honey Cinnamon Banana with Chocolate","emoji":"🍞","description":"French Toast","servings":1,"time":"27 min","difficulty":"Easy","ingredients":[{"name":"Brioche","quantity":"1"},{"name":"Butter","quantity":"10 gm"},{"name":"Banana","quantity":"1"},{"name":"Honey","quantity":"5 gm"},{"name":"Cinnamon","quantity":"5 gm"},{"name":"Milk Maid","quantity":"5 gm"},{"name":"Brown Sugar powder","quantity":"5 gm"},{"name":"Milk","quantity":"20 ml"},{"name":"Chocolate sauce","quantity":"5 ml"},{"name":"Whipping Cream","quantity":"10 gm"}],"steps":[{"ingredient":"","quantity":"","placement":"","action":"Take a Brioche bread slice.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Dip it into the mixture of 20 ml Milk, Brown sugar, milkmaid & cinnamon for 5 mins.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Put butter on pan then place bread on it until its brown","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Slice 1 banana into pieces.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Place the bread on the plate. put bananas","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Put 3 spots of Whipping cream as per video","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Sprinkle cinnamon powder","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Drizzle honey on top of everything","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Drizzle with Chocolate Sauce","duration":""}],"category":"food"}');
INSERT OR REPLACE INTO recipes (id, category, title, data_json) VALUES ('french-toast-velvet-tiramisu-indulgence', 'food', 'French Toast Velvet Tiramisu Indulgence', '{"id":"french-toast-velvet-tiramisu-indulgence","name":"French Toast Velvet Tiramisu Indulgence","emoji":"🍞","description":"French Toast","servings":1,"time":"24 min","difficulty":"Easy","ingredients":[{"name":"Brioche","quantity":"1"},{"name":"Brown Sugar powder","quantity":"5 gm"},{"name":"Milk","quantity":"30 ml"},{"name":"Butter","quantity":"10 gm"},{"name":"Espresso","quantity":"15 ml"},{"name":"Water","quantity":"10 ml"},{"name":"Mascarpone","quantity":"20 ml"},{"name":"Whipping cream","quantity":"15 gm"},{"name":"Condensed Milk","quantity":"10 gm"},{"name":"Instant Coffee Powder","quantity":"5 gm"},{"name":"Coco powder","quantity":"5 gm"}],"steps":[{"ingredient":"","quantity":"","placement":"","action":"Take one slice Brioche bread slice and Dip it into the mixture of 20 ml milk, brown sugar and milkmaid for 5 mins.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Put butter on a pan then place bread on it until it turns brown.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Place the bread in a serving plate.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Put diluted espresso on the bread (15 ml espresso + 10 ml water)","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Put Mascarpone cream on bread using a cone","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Make Milk spread 15 gm Cream cheese, 10 ml Milk, 5 gm Instant coffee Powder, 10 ml Condensed milk.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Pour it on bread.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Sprinkle coco powder in the end.","duration":""}],"category":"food"}');
INSERT OR REPLACE INTO recipes (id, category, title, data_json) VALUES ('french-toast-blueberry-cream-cheese-pistachio', 'food', 'French Toast Blueberry Cream Cheese Pistachio', '{"id":"french-toast-blueberry-cream-cheese-pistachio","name":"French Toast Blueberry Cream Cheese Pistachio","emoji":"🍞","description":"French Toast","servings":1,"time":"30 min","difficulty":"Easy","ingredients":[{"name":"Brioche bread","quantity":"1"},{"name":"Condensed milk","quantity":"10 gm"},{"name":"Blueberry compote","quantity":"15 ml"},{"name":"Brown Sugar powder","quantity":"5 gm"},{"name":"Milk","quantity":"25 ml"},{"name":"Milk Maid","quantity":"5 gm"},{"name":"Pistachio paste","quantity":"15 gm"},{"name":"Cream cheese","quantity":"30 gm"},{"name":"Rosemary","quantity":"1 piece"}],"steps":[{"ingredient":"","quantity":"","placement":"","action":"Take Brioche bread slice.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Dip it into the mixture of milk 20 ml, brown sugar, cinnamon 5 gm,milkmaid for 5 mins.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Put butter on pan then place bread on it until its brown","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Place the bread on the plate.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Put scoop of cream cheese 15 gm on the bread","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Take 15 gm measuring spoon. hold it under hot water for 5 sec then make a cavity on the cream cheese scoop.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Put blueberry compote 30 gm on the cavity made on the cream on bread.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Make spread of cream cheese 15 gm, whipping cream 10 ml, Pistachio spread 15 gm, milk 10 ml.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Give it to customer to pour the spread in plate.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Place the single rosemary on the cream cheese for garnish","duration":""}],"category":"food"}');
INSERT OR REPLACE INTO recipes (id, category, title, data_json) VALUES ('vadapaav-soft-shell-tacos', 'food', 'Vadapaav Soft Shell Tacos', '{"id":"vadapaav-soft-shell-tacos","name":"Vadapaav Soft Shell Tacos","emoji":"🌮","description":"Taco","servings":1,"time":"54 min","difficulty":"Easy","ingredients":[{"name":"Regular (White) Tortilla Wrap","quantity":"1"},{"name":"Butter","quantity":"5 gm"},{"name":"Thecha","quantity":"0.25 gm"},{"name":"Batata Wada Tikki (2)","quantity":"2*40gm"},{"name":"Pickled Red Cabbage","quantity":"6 gm"},{"name":"Pickled Red Onion","quantity":"6 gm"},{"name":"Cilantro Mayo","quantity":"30 gm"},{"name":"Vara Pav Dry Chutney","quantity":"3 gm"},{"name":"Green Chilli","quantity":"2 piece or 3 gm"},{"name":"Sriracha Schezwan Dip","quantity":"10 gm"}],"steps":[{"ingredient":"","quantity":"","placement":"","action":"Switch on the Deep fryer at full heat.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Wait for 3 minutes and then pull the heat down to 150.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Put 2 Batata Wada Tikki in the Deep fryer.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Fry for 3-4 minutes or until slight golden.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"While the Tikki is being fried warm or lightly toast the regular White Tortilla with butter on the pan on induction.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Spread Thecha on the Tortilla.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Spread Cilantro Mayo on the Tortilla.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Spread the Dry Vada Paav Chutney on the tortilla.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Place 2 fried vada on the tortilla.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add Pickled Onions.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add Pickled Cabbages.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Put Vertical Plates in the Griller.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Apply Butter on both sides.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Fold the tortilla in half and Place the folded tortillas.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Grill for 3 minutes.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Cut the tacos in two pieces and serve in Big Rectangular Plate.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Sides with Cilantro mayo (15 gm) as a dip.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"No spoon or knife to be served.","duration":""}],"category":"food"}');
INSERT OR REPLACE INTO recipes (id, category, title, data_json) VALUES ('thecha-korean-bun', 'food', 'Thecha Korean Bun', '{"id":"thecha-korean-bun","name":"Thecha Korean Bun","emoji":"🍞","description":"Bun","servings":1,"time":"27 min","difficulty":"Easy","ingredients":[{"name":"Korean Bun","quantity":"1"},{"name":"Thecha","quantity":"1 gm"},{"name":"Cream Cheese","quantity":"35 gm"},{"name":"Mozzarella","quantity":"5 gm"},{"name":"Parsley","quantity":"0.1 gm"},{"name":"Salt","quantity":"1 gm"},{"name":"Pepper","quantity":"1 gm"},{"name":"Oregano","quantity":"0.5 gm"},{"name":"Chilli Flakes","quantity":"0.5 gm"},{"name":"Garlic Butter","quantity":"5 gm"}],"steps":[{"ingredient":"","quantity":"","placement":"","action":"Take out the Thecha Korean Bun from the freezer.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Remove the cling wrap.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Microwave the Bun for 60 sec, on a ceramic plate.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Check the center bottom for hardness.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Apply Garlic Butter on Thecha Korean Bun, using the brush.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add a piece of Parsley on the centre of the Bun.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Transfer to a serving plate.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add Chilli Flakes for final dressing.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Serve with a fork and a knife.","duration":""}],"category":"food"}');
INSERT OR REPLACE INTO recipes (id, category, title, data_json) VALUES ('samosa-quesadilla', 'food', 'Samosa Quesadilla', '{"id":"samosa-quesadilla","name":"Samosa Quesadilla","emoji":"🫓","description":"Quesadilla","servings":1,"time":"39 min","difficulty":"Easy","ingredients":[{"name":"Regular (White) Tortilla Wrap","quantity":"1"},{"name":"Soy Sauce","quantity":"15 gm"},{"name":"Schezwan Sauce","quantity":"20 Gm"},{"name":"Grilled Capsicum","quantity":"15 gm"},{"name":"Samosa","quantity":"2 piece"},{"name":"Mozzarella Cheese","quantity":"20 gm"},{"name":"Butter","quantity":"5 gm"},{"name":"Schezwan Sriracha Dip","quantity":"30 gm"},{"name":"Green Chilli","quantity":"2 piece or 3 gm"}],"steps":[{"ingredient":"","quantity":"","placement":"","action":"Switch on the Deep fryer at full heat","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Wait for 3 minutes and then pull the heat down to 150","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Put Samosas in the Deep fryer","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Fry for 3-4 minutes or until slight golden","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Warm tortilla on a pan with some butter","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Mix schezwan & soy sauce then apply to the tortilla","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Cut Tortilla in 4 parts like a pizza","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Cut the samosa in 4 parts","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Crush samosa and spread on all 4 parts","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Put mozzarella cheese and capsicum on samosas","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Fold the tortillas in half","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Place all 4 tortillas in the grilling machine with correct plates, apply butter and for 5 mins until light brown","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Plate and Serve with Schezwan Sriracha Dip","duration":""}],"category":"food"}');
