INSERT OR REPLACE INTO recipes (id, category, title, data_json) VALUES ('avocado-guacamole-pesto-sourdough-toast', 'food', 'Avocado Guacamole Pesto Sourdough Toast', '{"id":"avocado-guacamole-pesto-sourdough-toast","name":"Avocado Guacamole Pesto Sourdough Toast","emoji":"🍞","description":"Toast","servings":1,"time":"33 min","difficulty":"Easy","ingredients":[{"name":"Sourdough Bread ( 1 piece)","quantity":"20 gm"},{"name":"Butter","quantity":"3 gm"},{"name":"Pesto Sauce","quantity":"20 gm"},{"name":"Buffalo Mozzarella","quantity":"30 gm"},{"name":"Avocado","quantity":"50 gm"},{"name":"Salt","quantity":"1 gm"},{"name":"Pepper","quantity":"1 gm"},{"name":"Onion","quantity":"3 gm"},{"name":"Tomato","quantity":"3 gm"},{"name":"Lemon","quantity":"0.1 gm"},{"name":"Micro Herbs","quantity":"2 gm"},{"name":"Edible Flower","quantity":"1 gm"}],"steps":[{"ingredient":"","quantity":"","placement":"","action":"Steps to make guacamole: 1/2 avacado half and warm it for 30sec and smash it using fork","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Fine chopped 2 gm tomato","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Fine chopped 2 gm onion","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Pinch of salt and pepper","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Mix all the above together using fork and gucamole is ready","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Apply butter on sourdough bread and toast it","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Apply pesto sauce followed by Minced/Sliced buffala mozzarella","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Put guacamole on the toast and season with olive oil","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Top with micro herbs and edible flowers","duration":""}],"category":"food"}');
