INSERT OR REPLACE INTO recipes (id, category, title, data_json) VALUES ('margherita-flatbread-pizza', 'food', 'Margherita Flatbread Pizza', '{"id":"margherita-flatbread-pizza","name":"Margherita Flatbread Pizza","emoji":"🍕","description":"Flatbread Pizza","servings":1,"time":"33 min","difficulty":"Easy","ingredients":[{"name":"Flat Bread","quantity":"1 Piece"},{"name":"Pizza Pasta Sauce","quantity":"25 gm"},{"name":"Mozzarella Cheese","quantity":"30 gm"},{"name":"Sundried Tomato","quantity":"3 pieces OR 6 gm"},{"name":"Olives","quantity":"4 pieces OR 10 gm"},{"name":"Basil Leaves","quantity":"4 pieces OR 1 gm"},{"name":"Olive Oil","quantity":"5 gm"},{"name":"Oregano Sachet (Serve Seperately)","quantity":"1 Piece"},{"name":"Chilli Flakes Sachet (Serve Seperately)","quantity":"1 Piece"}],"steps":[{"ingredient":"","quantity":"","placement":"","action":"Preheat oven (OTG) to 220°C (430°F).","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Spread Pizza Pasta sauce on the Flatbread.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add 30 gm mozzarella","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Then add vertically sliced sundried tomatoes","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Then add sliced black olives.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Bake for 5-6 mins until crust is golden and cheese is melted at 180°C.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add Basil leaves if available","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Cut the pizza into 6 pieces","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Take petal shaped plate","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Put pizza on that plate","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Serve the pizza with oregano and chilli flakes satchet","duration":""}],"category":"food"}');
