INSERT OR REPLACE INTO recipes (id, category, title, data_json) VALUES ('pesto-flatbread-pizza', 'food', 'Pesto Flatbread Pizza', '{"id":"pesto-flatbread-pizza","name":"Pesto Flatbread Pizza","emoji":"🍕","description":"Flatbread Pizza","servings":1,"time":"39 min","difficulty":"Easy","ingredients":[{"name":"Flat Bread","quantity":"1 Piece"},{"name":"Pesto Sauce","quantity":"25 gm"},{"name":"Mozzarella Cheese","quantity":"30 gm"},{"name":"Cherry Tomato","quantity":"10 gm"},{"name":"Rocket","quantity":"5 gm"},{"name":"Black Olives","quantity":"5 gm"},{"name":"Capsicum","quantity":"10 gm"},{"name":"Oregano Sachet Separate","quantity":"1 Piece"},{"name":"Chilli Flakes Sachet Separate","quantity":"1 Piece"}],"steps":[{"ingredient":"","quantity":"","placement":"","action":"Preheat oven (OTG) to 220°C (430°F).","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Spread pesto generously over the Flatbread.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Then add mozzarella cheese.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add sliced cherry tomato.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add vertically chopped capsicum.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add sliced olives.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Bake for 5-7 mins until golden and bubbly at 180°C.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Top with fresh arugula.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add a drizzle of olive oil.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Cut the pizza into 6 pieces.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Take petal shaped plate.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Put pizza on that plate.","duration":""},{"ingredient":"","quantity":"","placement":"