INSERT OR REPLACE INTO recipes (id, category, title, data_json) VALUES ('pesto-croissant-sandwich', 'food', 'Pesto Croissant Sandwich', '{"id":"pesto-croissant-sandwich","name":"Pesto Croissant Sandwich","emoji":"🥐","description":"Croissant","servings":1,"time":"36 min","difficulty":"Easy","ingredients":[{"name":"Butter Croissant","quantity":"1 Piece"},{"name":"Pesto","quantity":"20 gm"},{"name":"Arugula / Rocquette Leaves","quantity":"10 gm"},{"name":"Cherry Tomato","quantity":"15 gm"},{"name":"Buffalo Mozzarella","quantity":"30 gm"},{"name":"Microgreens","quantity":"5 gm"},{"name":"Edible flowers","quantity":"2"}],"steps":[{"ingredient":"","quantity":"","placement":"","action":"Cut open croissant in half.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Microwave for 10 sec.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Apply butter both sides.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Warm lightly toast in the oven (OTG). 3 mins at 180°C.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Apply Pesto on both sides","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add Buffalo mozzarella, add Arugula (Rocquette Leaves).","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Slice cherry tomatoes","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Caramelise the tomatoes.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add the tomatoes.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Top it up with Microgreens and Edible Flowers if available","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Do not heat in microwave or OTG again.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"It is to be served as cold sandwich.","duration":""}],"category":"food"}');
