INSERT OR REPLACE INTO recipes (id, category, title, data_json) VALUES ('loaded-mushroom-croissant-sandwich', 'food', 'Loaded Mushroom Croissant Sandwich', '{"id":"loaded-mushroom-croissant-sandwich","name":"Loaded Mushroom Croissant Sandwich","emoji":"🥐","description":"Croissant","servings":1,"time":"42 min","difficulty":"Easy","ingredients":[{"name":"Croissant","quantity":"1"},{"name":"Butter","quantity":"10 gm"},{"name":"Confit Garlic","quantity":"5 gm"},{"name":"cheese slice","quantity":"2"},{"name":"Oregano, chili flakes","quantity":"4 gm"},{"name":"Mushroom","quantity":"40 gm"},{"name":"Salt","quantity":"2 gm"},{"name":"Pepper","quantity":"2 gm"},{"name":"Hot Honey","quantity":"10 gm"}],"steps":[{"ingredient":"","quantity":"","placement":"","action":"Toast the Croissant after cutting in half until golden and crisp.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Apply the confit garlic spread on toasted croissant and spread.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Take 40 gm sautéed mushroom in a plate and microwave it for 20 sec.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add 2 cheese slice to it.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add oregano.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add pinch of salt.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add pinch of black pepper.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add chilli flakes.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Again microwave till cheese slices are melted (20 sec).","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Mix it all well.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"apply this mushroom mix on the croissant.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"put hot honey on it and 