INSERT OR REPLACE INTO recipes (id, category, title, data_json) VALUES ('Blue-Pea-Tea-Iced-Latte', 'seasonal', 'Blue Pea Tea Iced Latte', '{"id":"Blue-Pea-Tea-Iced-Latte","name":"Blue Pea Tea Iced Latte","emoji":"🧋","description":"Iced Drink","category":"special-drinks","drinkType":"iced","servings":1,"time":"5 min","difficulty":"Medium","temperatures":{"hot":false,"cold":true},"sizes":{"175ml":false,"250ml":true,"325ml":true,"350ml":true},"ingredients":[{"name":"Water","quantity":"40 ml"},{"name":"Milk","quantity":"75 ml"},{"name":"Whip Cream","quantity":"45 gm"},{"name":"Espresso","quantity":"45 ml"},{"name":"Ice","quantity":"120 gm"},{"name":"Blue Pea Tea Flowers","quantity":"0.5 gm or 3 teaspoons"}],"ingredientVariants":{"cold":{"250ml":[{"name":"Water","quantity":"30 ml"},{"name":"Milk","quantity":"  60 ml"},{"name":"Whip Cream","quantity":"30 gm"},{"name":"Espresso","quantity":"30 ml"},{"name":"Ice","quantity":"100 gm"},{"name":"Blue Pea Tea Flowers","quantity":"0.25 gm or 2 teaspoons"}],"325ml":[{"name":"Water","quantity":"40 ml"},{"name":"Milk","quantity":"75 ml"},{"name":"Whip Cream","quantity":"45 gm"},{"name":"Espresso","quantity":"45 ml"},{"name":"Ice","quantity":"120 gm"},{"name":"Blue Pea Tea Flowers","quantity":"0.5 gm or 3 teaspoons"}],"350ml":[{"name":"Water","quantity":"40 ml"},{"name":"Milk","quantity":"75 ml"},{"name":"Whip Cream","quantity":"45 gm"},{"name":"Espresso","quantity":"45 ml"},{"name":"Ice","quantity":"140 gm"},{"name":"Blue Pea Tea Flowers","quantity":"0.5 gm or 3 teaspoons"}]}},"steps":[{"ingredient":"","quantity":"","placement":"","action":"Brew Blue Pea Tea Flowers in hot water in a French Press for 3 minutes.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"In a cup, take milk and add Blue Pea Tea Concoction using a filter. The milk will turn blue.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Pull out a shot of espresso.","duration":""},{"ingredient":"","quantity":"","placement":"