INSERT OR REPLACE INTO recipes (id, category, title, data_json) VALUES ('Tiramisu-Iced-Latte', 'seasonal', 'Tiramisu Iced Latte', '{"id":"Tiramisu-Iced-Latte","name":"Tiramisu Iced Latte","emoji":"🍰","description":"Iced Drink","category":"special-drinks","drinkType":"iced","servings":1,"time":"5 min","difficulty":"Medium","temperatures":{"hot":false,"cold":true},"sizes":{"175ml":false,"250ml":true,"325ml":true,"350ml":true},"ingredients":[{"name":"Whip Cream","quantity":"45 gm"},{"name":"Milk","quantity":"90 ml"},{"name":"Tiramisu Syrup of cold foam","quantity":"22 ml"},{"name":"Espresso","quantity":"45 ml"},{"name":"Ice","quantity":"120 gm"},{"name":"Tiramisu Syrup for milk","quantity":"10 ml"},{"name":"Coco Powder","quantity":"1 dash"},{"name":"Ladyfinger Biscuit (Tiramisu Biscuit)","quantity":"1"}],"ingredientVariants":{"cold":{"250ml":[{"name":"Whip Cream","quantity":"30 gm"},{"name":"Milk","quantity":"60 ml"},{"name":"Tiramisu Syrup of cold foam","quantity":"15 ml"},{"name":"Espresso","quantity":"30 ml"},{"name":"Ice","quantity":"100 gm"},{"name":"Tiramisu Syrup for milk","quantity":"7.5 ml"},{"name":"Coco Powder","quantity":"1 dash"},{"name":"Ladyfinger Biscuit (Tiramisu Biscuit)","quantity":"1"}],"325ml":[{"name":"Whip Cream","quantity":"45 gm"},{"name":"Milk","quantity":"90 ml"},{"name":"Tiramisu Syrup of cold foam","quantity":"22 ml"},{"name":"Espresso","quantity":"45 ml"},{"name":"Ice","quantity":"120 gm"},{"name":"Tiramisu Syrup for milk","quantity":"10 ml"},{"name":"Coco Powder","quantity":"1 dash"},{"name":"Ladyfinger Biscuit (Tiramisu Biscuit)","quantity":"1"}],"350ml":[{"name":"Whip Cream","quantity":"45 gm"},{"name":"Milk","quantity":"90 ml"},{"name":"Tiramisu Syrup of cold foam","quantity":"22 ml"},{"name":"Espresso","quantity":"45 ml"},{"name":"Ice","quantity":"140 gm"},{"name":"Tiramisu Syrup for milk","quantity":"10 ml"},{"name":"Coco Powder","quantity":"1 dash"},{"name":"Ladyfinger Biscuit (Tiramisu Biscuit)","quantity":"1"}]}},"steps":[{"ingred