INSERT OR REPLACE INTO recipes (id, category, title, data_json) VALUES ('Vietnamese-shakerato', 'seasonal', 'Vietnamese Shakerato', '{"id":"Vietnamese-shakerato","name":"Vietnamese Shakerato","emoji":"🥤","description":"Iced Drink","category":"special-drinks","drinkType":"iced","servings":1,"time":"5 min","difficulty":"Medium","temperatures":{"hot":false,"cold":true},"sizes":{"175ml":false,"250ml":true,"325ml":true,"350ml":true},"ingredients":[{"name":"Ice","quantity":"120 gm"},{"name":"Condensed Milk","quantity":"45 gm"},{"name":"Espresso","quantity":"90 ml"},{"name":"Milk","quantity":"60 ml"},{"name":"Cinnamon powder","quantity":"3 dash"},{"name":"Mint","quantity":"6 leaves"}],"ingredientVariants":{"cold":{"250ml":[{"name":"Ice","quantity":"100 gm"},{"name":"Condensed Milk","quantity":"30 gm"},{"name":"Espresso","quantity":"60 ml"},{"name":"Milk","quantity":"60 ml"},{"name":"Cinnamon powder","quantity":"2 dash"},{"name":"Mint","quantity":"4 leaves"}],"325ml":[{"name":"Ice","quantity":"120 gm"},{"name":"Condensed Milk","quantity":"45 gm"},{"name":"Espresso","quantity":"90 ml"},{"name":"Milk","quantity":"60 ml"},{"name":"Cinnamon powder","quantity":"3 dash"},{"name":"Mint","quantity":"6 leaves"}],"350ml":[{"name":"Ice","quantity":"140 gm"},{"name":"Condensed Milk","quantity":"45 gm"},{"name":"Espresso","quantity":"90 ml"},{"name":"Milk","quantity":"60 ml"},{"name":"Cinnamon powder","quantity":"3 dash"},{"name":"Mint","quantity":"6 leaves"}]}},"steps":[{"ingredient":"","quantity":"","placement":"","action":"Pull out an espresso shot but do not add in the shaker yet.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Take the Bar Shaker and put it on weighing scale. Set the weight to zero (Tare).","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add Condensed Milk in the shaker by weight (gm).","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Measure milk in ''ml'' and Add in the shaker.","duration":""},{