INSERT OR REPLACE INTO master_components (id, name, data_json) VALUES ('comp-thecha-sauce', 'Thecha Sauce', '{"id":"comp-thecha-sauce","name":"Thecha Sauce","emoji":"🥫","description":"Base Recipe","category":"component","yield":"","servings":1,"time":"","difficulty":"Easy","ingredients":[{"name":"Roasted Green Chilli","quantity":"100 gm"},{"name":"Garlic","quantity":"30 gm"},{"name":"Peanut","quantity":"50 gm"},{"name":"Coriander","quantity":"100 gm"},{"name":"Jeera","quantity":"20 gm"},{"name":"Sunflower Oil","quantity":"50 gm"},{"name":"Salt","quantity":"5 gm"}],"steps":[{"ingredient":"","quantity":"","placement":"","action":"Wash the green chillies.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Remove the top ends of all chillies.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Switch on the induction at 1000 power.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Light roast the peanuts.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Put the roasted the peanuts in ceramic plate.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Put the chillies in pan and roast the chillies for 5 mins","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Put the chillies in another plate.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Let the chillies and peanuts cool down.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"In the meanwhile clean the corriander.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Grinder the peanuts using the small grinder.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Put the grinded peanuts in plate.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Now grind the jeera.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Put garlic in the same grinder.","duration":""},{"ingred