INSERT OR REPLACE INTO master_components (id, name, data_json) VALUES ('comp-spicy-hummus', 'Spicy Hummus', '{"id":"comp-spicy-hummus","name":"Spicy Hummus","emoji":"🥫","description":"Base Recipe","category":"component","yield":"","servings":1,"time":"","difficulty":"Easy","ingredients":[{"name":"Chickpeas","quantity":"150 gm"},{"name":"Tahini","quantity":"20 gm"},{"name":"Garlic Chilli Sauce","quantity":"30 gm"},{"name":"Olive Oil","quantity":"25 gm"},{"name":"Ice Cubes (add ice while blending)","quantity":"8 gm"},{"name":"Salt","quantity":"3 gm"}],"steps":[{"ingredient":"","quantity":"","placement":"","action":"Soak the Chickpeas for 5 hours or overnight.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Boil Chickpeas in cooker at 1000 power on induction.Wait till 5 whistles.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Let the boiled Chickpeas cool down.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Grind the boiled Chickpeas using a grinder and add ice while grinding.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Make tahini using sesame seeds and water in the grinder.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Take everything in a mixing bowl.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add chilli garlic sauce/paste as per the weight.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add olive oil in the grinder and grind things together.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Blend until smooth, adding ice gradually to adjust texture.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add salt.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Spicy hummus is ready.","duration":""}]}');
INSERT OR REPLACE INTO master_components (id, name, data_json) VALUES ('comp-thecha-korean-bun', 'Thecha Korean Bun', '{"id":"comp-thecha-korean-bun","name":"Thecha Korean Bun","emoji":"🍞","description":"Base Recipe","category":"component","yield":"","servings":1,"time":"","difficulty":"Easy","ingredients":[{"name":"Korean Bun","quantity":"1"},{"name":"Thecha","quantity":"1gm (use measuring spoon)"},{"name":"Cream Cheese","quantity":"35 gm"},{"name":"Mozzarella","quantity":"5 gm"},{"name":"Parsley","quantity":"2 gm"},{"name":"Salt","quantity":"2 gm"},{"name":"Pepper","quantity":"2 gm"},{"name":"Oregano","quantity":"0.5"},{"name":"Chilli Flakes","quantity":"0.25"}],"steps":[{"ingredient":"","quantity":"","placement":"","action":"Take cream cheese in a ceramic plate.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Warm the cream cheese for 15 sec in microwave to soften it.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Take mozzarella cheese in the same plate and warm it together for 10 sec.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Take this mixture in mixing bowl.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add theecha.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add oregano.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add chilli flakes.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add salt.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add pepper.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Mix everything together.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Take a piping bag.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Fill mixture in a piping bag. ","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Cut the Piping bag slightly from the end before adding the mixture.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Cut X shape into the bun without slicing through. There should be 8 cuts.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Fill the bun with the mixture.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add chilli flaxes and oregano.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add parsley leaf in the center.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Cover the bun with cling wrap and store it in freezer.","duration":""}]}');
INSERT OR REPLACE INTO master_components (id, name, data_json) VALUES ('comp-falafel', 'Falafel', '{"id":"comp-falafel","name":"Falafel","emoji":"🧆","description":"Base Recipe","category":"component","yield":"","servings":1,"time":"","difficulty":"Easy","ingredients":[{"name":"Soaked Chickpeas","quantity":"250 gm"},{"name":"Onion Rough Cut","quantity":"75 gm"},{"name":"Garlic","quantity":"12 gm"},{"name":"Coriander","quantity":"20 gm"},{"name":"Parsley","quantity":"30 gm"},{"name":"Cumin","quantity":"4 gm"},{"name":"Salt","quantity":"6 gm"},{"name":"Pepper","quantity":"2 gm"},{"name":"Baking Soda","quantity":"1 gm"},{"name":"Sesame Seed","quantity":"5 gm"}],"steps":[{"ingredient":"","quantity":"","placement":"","action":"Soak Chickpeas overnight (do not use canned).","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Drain thoroughly. ","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Take a grinder.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Grind the Chickpeas till fine.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add ice cube to smoothen the paste.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Take the grounded Chickpeas out in a bowl.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Grind onion and garlic.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add parsley and grind again till everything is coarse but sticky.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Take out the mixture in same bowl as Chickpeas.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add baking soda to the mixture.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Mix everything well. ","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Store the falafel in a clean container in the refrigerator .","duration":""}]}');
INSERT OR REPLACE INTO master_components (id, name, data_json) VALUES ('comp-potato-masala-filling', 'Potato Masala Filling', '{"id":"comp-potato-masala-filling","name":"Potato Masala Filling","emoji":"🧆","description":"Base Recipe","category":"component","yield":"","servings":1,"time":"","difficulty":"Easy","ingredients":[{"name":"Sunflower oil","quantity":"8 gm"},{"name":"Mustard Seed","quantity":"3 gm"},{"name":"Curry Leaf","quantity":"2 gm"},{"name":"Ginger","quantity":"20 gm"},{"name":"Green Chilli","quantity":"15 gm"},{"name":"Turmeric","quantity":"3 gm"},{"name":"Boiled Mash Potato","quantity":"350 gm"},{"name":"Salt","quantity":"7 gm"},{"name":"Coriander","quantity":"7 gm"}],"steps":[{"ingredient":"","quantity":"","placement":"","action":"Heat oil in a pan. Add mustard seeds and let them crackle.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add urad dal (if using), then curry leaves, green chilies, and ginger. ","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add onions and sauté until soft and translucent.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add turmeric and mix well.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add boiled potatoes, salt, and a splash of water. Mix and mash lightly. ","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Cook for 3 to 4 minutes until well combined.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Finish with lemon juice and chopped coriander.","duration":""}]}');
INSERT OR REPLACE INTO master_components (id, name, data_json) VALUES ('comp-mint-cilantro-sauce', 'Mint Cilantro Sauce', '{"id":"comp-mint-cilantro-sauce","name":"Mint Cilantro Sauce","emoji":"🥫","description":"Base Recipe","category":"component","yield":"","servings":1,"time":"","difficulty":"Easy","ingredients":[{"name":"Blanched Coriander","quantity":"100 gm"},{"name":"Green Chilli","quantity":"1 chilli (1-3 gm)"},{"name":"Mint Leaf Paste","quantity":"25 gm"},{"name":"Eggless Mayo","quantity":"250 gm"},{"name":"Lemon Juice","quantity":"5 gm"},{"name":"Salt","quantity":"2 gm"}],"steps":[{"ingredient":"","quantity":"","placement":"","action":"Take the grinder.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add the mint in the grinder and grind it into a paste form.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Fine chop the coriander. ","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Then add the coriander and green chilli to the grinder .","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Grind everything together.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"In a mixing bowl add all prepared ingredients.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add the lemon juice.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add salt and mix everything together.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Store in a squeeze bottle in the fridge for 3-4 days.","duration":""}]}');
INSERT OR REPLACE INTO master_components (id, name, data_json) VALUES ('comp-sriracha-schezwan-sauce', 'Sriracha Schezwan Sauce', '{"id":"comp-sriracha-schezwan-sauce","name":"Sriracha Schezwan Sauce","emoji":"🥫","description":"Base Recipe","category":"component","yield":"150 gm","servings":1,"time":"","difficulty":"Easy","ingredients":[{"name":"Eggless Mayo","quantity":"50 gm"},{"name":"chilli garlic Sauce","quantity":"50 gm"},{"name":"Schezwan Sauce","quantity":"50 gm"}],"steps":[{"ingredient":"","quantity":"","placement":"","action":"Take a weighing scale.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Place a container on the weighing scale.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Tear the weight.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add the mayo.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Tear the weight.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add the Schezwan Sauce.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Tear the weight.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add the Chilli garlic Sauce.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Mix everything well.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Store in a squeeze bottle and store in the fridge.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Use within 3-4 days","duration":""}]}');
INSERT OR REPLACE INTO master_components (id, name, data_json) VALUES ('comp-pesto', 'PESTO', '{"id":"comp-pesto","name":"PESTO","emoji":"🥫","description":"Base Recipe","category":"component","yield":"","servings":1,"time":"","difficulty":"Easy","ingredients":[{"name":"Cleaned Basil Leaves","quantity":"500 gms"},{"name":"Garlic Peeled","quantity":"50 gm"},{"name":"Amul Cheese Cube","quantity":"3 cubes"},{"name":"Olive Oil","quantity":"100 ml"},{"name":"Walnuts","quantity":"30 gm"},{"name":"Salt","quantity":"4 gm"},{"name":"Black Pepper","quantity":"2 gm"}],"steps":[{"ingredient":"","quantity":"","placement":"","action":"Take all the basil leaves in a big contaner.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Remove the steams from the leaves.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Use the leaves only.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Clean the basil leaves with water.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Take the cheese cubes out of freezer.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Put the cubes in hot water cup","duration":""},{"ingredient":"","quantity":"","placement":"","action":"The the grinder and grind the basil leaves with little amount of water to make a thick paste.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Take walnuts in the in the grinder and grind it in paste.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Put the walnut paste in the grounded pesto.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Grind the garlic in the grinder.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add some basil paste to the grinder and again grind it with garlic paste.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add the black pepper and salt and again grind it.","duration":""},{"ingr