INSERT OR REPLACE INTO master_components (id, name, data_json) VALUES ('comp-crumbles-for-muffins', 'Crumbles for Muffins', '{"id":"comp-crumbles-for-muffins","name":"Crumbles for Muffins","emoji":"🍰","description":"Base Recipe","category":"component","yield":"","servings":1,"time":"","difficulty":"Easy","ingredients":[{"name":"Maida","quantity":"60 gm"},{"name":"Sugar","quantity":"100 gm"},{"name":"Salt","quantity":"2 gm"},{"name":"Butter","quantity":"56 gm"}],"steps":[{"ingredient":"","quantity":"","placement":"","action":"Add Maida, Sugar and Salt in a bowl and whisk thoroughly","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add butter and mix using hand, It will break down and form crumbles","duration":""}]}');
INSERT OR REPLACE INTO master_components (id, name, data_json) VALUES ('comp-samosa', 'Samosa', '{"id":"comp-samosa","name":"Samosa","emoji":"🧆","description":"Base Recipe","category":"component","yield":"","servings":1,"time":"","difficulty":"Easy","ingredients":[{"name":"Potato","quantity":"500 gm"},{"name":"Water","quantity":"500 ml"},{"name":"Maida","quantity":"500 gm"},{"name":"Ajwain","quantity":"5 gm"},{"name":"Salt","quantity":"5 gm"},{"name":"Oil","quantity":"60 ml"},{"name":"Cumin Seeds","quantity":"5 gm"},{"name":"Ginger","quantity":"5 gm"},{"name":"Hing (Asafoetida)","quantity":"0.5 gm"},{"name":"Green chilli (2 chillies)","quantity":"5 gm"},{"name":"Salt","quantity":"2.5 gm"},{"name":"Amchur Powder","quantity":"2.5 gm"},{"name":"Fennel Powder","quantity":"2.5 ml"},{"name":"Coriander leaves","quantity":"5 gm"},{"name":"Curry Leaves","quantity":"5 gm"}],"steps":[{"ingredient":"","quantity":"","placement":"","action":"Cut 3 to 4 medium Potatoes in half and pressure cook for 3 whistles","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Let them Cool and crumble them and keep aside.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Switch on the induction.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Put a frying pan.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add some oil to the pan.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Once teh oil is heated add the cumin seeds.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add Hing.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add green chiili.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add Haldi.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add Coriander powder.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"In a mixing bowl take Maida.","duration":""},{"ing