INSERT OR REPLACE INTO master_components (id, name, data_json) VALUES ('comp-chocolate-ganache', 'Chocolate Ganache', '{"id":"comp-chocolate-ganache","name":"Chocolate Ganache","emoji":"🍫","description":"Base Recipe","category":"component","yield":"","servings":1,"time":"","difficulty":"Easy","ingredients":[{"name":"Dark chocolate compound","quantity":"150 gm"},{"name":"Fresh Cream","quantity":"200 gm"}],"steps":[{"ingredient":"","quantity":"","placement":"","action":"Take 200 gm dark chocolate slab.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Make small pieces of it.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Melt the chocolate in microwave.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Take 200 gram fresh cream in a cup/container.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Melt the cream in microwave.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Mix the melted chocolate and cream .","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Keep this ganache aside now.","duration":""}]}');
INSERT OR REPLACE INTO master_components (id, name, data_json) VALUES ('comp-brioche-bread', 'Brioche Bread', '{"id":"comp-brioche-bread","name":"Brioche Bread","emoji":"🍞","description":"Base Recipe","category":"component","yield":"","servings":1,"time":"","difficulty":"Easy","ingredients":[{"name":"Maida","quantity":"440 gm (3.5 cups)"},{"name":"Yeast","quantity":"12 gm (2.5 teaspoon)"},{"name":"Salt","quantity":"7 gm (1.5 teaspoon)"},{"name":"Sugar","quantity":"30 gm (1/4 Cup)"},{"name":"Warm milk (38-40 degree celcius)","quantity":"250 ml (1 cup)"},{"name":"Yogurt / Milk Powder","quantity":"30 ml ( 2 tablespoon)"},{"name":"Milk If needed","quantity":"30 ml ( 2 tablespoon)"}],"steps":[{"ingredient":"","quantity":"","placement":"","action":"Mix flour, yeast, sugar, and salt in a large bowl.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add warm milk and yogurt. Mix until dough forms.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Knead for 3-4 minutes, then gradually add butter 1 tbsp at a time. Continue kneading 8-10 minutes until smooth and elastic.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Place in greased bowl, cover, and rise 1.5-2 hours until doubled.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Shape into loaf or rolls. Place in greased 8x4 inch pan or molds.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Cover and rise 45-60 minutes until dough rises above pan.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Preheat oven to 180°C. Brush top with milk and bake 25-30 minutes for loaf or 18-20 minutes for rolls until golden.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Cool on wire rack before slicing.","duration":""}]}');
INSERT OR REPLACE INTO master_components (id, name, data_json) VALUES ('comp-vara-pav-dry-chutney', 'Vara Pav Dry Chutney', '{"id":"comp-vara-pav-dry-chutney","name":"Vara Pav Dry Chutney","emoji":"🥫","description":"Base Recipe","category":"component","yield":"","servings":1,"time":"","difficulty":"Easy","ingredients":[{"name":"Roasted Peanuts","quantity":"50 gm"},{"name":"Roasted Red chilli","quantity":"3"},{"name":"Chilli powder","quantity":"2 gm"},{"name":"jeera","quantity":"15 gm"},{"name":"Salt","quantity":"3 gm"},{"name":"Garlic","quantity":"10 gm"}],"steps":[{"ingredient":"","quantity":"","placement":"","action":"Take red chillies as per the weight mentioned.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Remove the top ends of all chillies.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Switch on the induction at 1000 power.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Light roast the peanuts.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Put the roasted the peanuts in ceramic plate.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Put the chillies in pan and roast the chillies for 5 mins","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Put the chillies in another plate.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Let the chillies and peanuts cool down.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Grinder the peanuts using the small grinder.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Put the grinded peanuts in plate.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Now grind the jeera.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Put garlic in the same grinder.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add salt and chilli in the same grinder. ","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add the grounded peanuts and grind everything together.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Mix everything together.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"The vadapav dry chutney is ready.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Store it in clean container in the shelves.","duration":""}]}');
INSERT OR REPLACE INTO master_components (id, name, data_json) VALUES ('comp-banana-walnut-bread', 'BANANA WALNUT BREAD', '{"id":"comp-banana-walnut-bread","name":"BANANA WALNUT BREAD","emoji":"🍞","description":"Base Recipe","category":"component","yield":"","servings":1,"time":"","difficulty":"Easy","ingredients":[{"name":"Banana - Medium Ripe","quantity":"4 pieces"},{"name":"Olive oil","quantity":"4 tbsp (4 tablespoon)\nOR 60 ml"},{"name":"Lactose Free Milk OR Almond Milk (if Lactose free milk is not available)","quantity":"180 ml\nor 12 tbsp\n(12 tablespoon)"},{"name":"Honey","quantity":"120 gm"},{"name":"Walnuts ","quantity":"25 gms"},{"name":"Cinnamon Powder","quantity":"1 tsp\n(1 teaspoon)\nOR 5 gm"},{"name":"Baking Powder","quantity":"1 tsp\n(1 teaspoon)\nOR 5 gm"},{"name":"Baking Soda","quantity":"1/2 tsp\n(half teaspoon)\nOR 2.5 gm"},{"name":"Salt","quantity":"2 pinch"},{"name":"Ragi Atta   (Ragi Flour)","quantity":"120 gm"},{"name":"Jowar Atta   (Jowar Flour)","quantity":"120 gm"}],"steps":[{"ingredient":"","quantity":"","placement":"","action":"Smash all 4 Bananas using a fork in a plate.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Transfer the smashed bananas in bowl.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add Olive Oil -  60 ml OR 4 Tablespoon.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add Lactose Free Milk  - 180 ml OR 12 Tablespoon\nOR Use Almond milk only if Lactose free milk is not available.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add Honey - 120 gm.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Roughly chop the Walnuts - 25 gm.\n-Put half in the mixture. \n-Save Half for topping, before putting in oven.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add Cinnamon Powder - 1 tsp (1 teaspoon) OR 5 gm.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add Baking Powder - 1 tsp (1 teaspoon) OR 5 gm.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add Baking Soda - 1/2 tsp (Half teaspoon) OR 2.5 gm.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add Salt - 2 Pinch.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add Ragi Atta - 120 gm.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add Jowar Atta - 120 gm.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Whisk the whole mixture using hand whisker.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Take the Rectangular Bread Baking tray and apply butter using the butter brush.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Use Non-Printed, Plain Butter Paper and put it on all inside walls of the baking tray and no tray should be visible.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Apply more butter on the butter paper using butter brush.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Transfer the whole mixture into the tray.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Top it with remaining Walnuts (12 gms) and spread evenly across the mixture.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Bake at 180 Degrees for 40 minutes.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"After 40 minutes - Insert a wooden stirrer in the bread and remove it.\n-If there is no residue on the stirrer, then Banana Walnut Bread is ready.\n-If there is residue sticking to the stirrer - then bake again for 10 minutes t 180 degrees. \n-Repeat process if necessary.\n","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Once Baked keep it at room temperature until it cools down post 1 Hour. ","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Remove loaf from the tray and Cut 1 inch slices.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"If there is space in undercounter, then keep the slices in the bread box in alluminium foil.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"If there is no space in undercounter - then cling wrap the bread slices tightly and store in Deep freezer","duration":""}]}');
INSERT OR REPLACE INTO master_components (id, name, data_json) VALUES ('comp-gucamole', 'Gucamole', '{"id":"comp-gucamole","name":"Gucamole","emoji":"🫙","description":"Base Recipe","category":"component","yield":"","servings":1,"time":"","difficulty":"Easy","ingredients":[{"name":"Avacado","quantity":"1/2"},{"name":"onion","quantity":"3 gm"},{"name":"tomato","quantity":"3 gm"},{"name":"salt","quantity":"2 gm"},{"name":"pepper","quantity":"2 gm"}],"steps":[{"ingredient":"","quantity":"","placement":"","action":"Steps to make guacamole:\n 1/2 avacado half and warm it for 30sec and smash it using fork.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Fine chopped 2 gm tomato.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Fine chopped 2 gm onion.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Pinch of salt and pepper.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Mix all the above together using fork and gucamole is ready.","duration":""}]}');
INSERT OR REPLACE INTO master_components (id, name, data_json) VALUES ('comp-almond-butter', 'Almond Butter', '{"id":"comp-almond-butter","name":"Almond Butter","emoji":"🧈","description":"Base Recipe","category":"component","yield":"","servings":1,"time":"","difficulty":"Easy","ingredients":[{"name":"Butter","quantity":"100 gm (softened butter)"},{"name":"Maida","quantity":"100 gm"},{"name":"Powdered sugar","quantity":"100 gm"},{"name":"Almond flour","quantity":"100 gm"}],"steps":[{"ingredient":"","quantity":"","placement":"","action":"Take almonds and soak it in warm water for 1 hour.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Take the weighing scale and measure the butter.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Keep it at room temperature so that it softens and is ready for use.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Take weighing scale and measure the sugar.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"If not grounded then make fine powder of sugar.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"After one hour throw the warm water and peal the almonds.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Take a pan and put it on induction at powder 1000.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Light roast the almonds for 5 mins to remove the moisture.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Take a grinder and grind the almonds to make almond flour.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Take a mixing bowl.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add maida.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add almond flour.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add powdered sugar.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add softened butter.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Mix them well.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Almond butter is ready.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Store them in a clean container and keep it in undercounter.","duration":""}]}');
INSERT OR REPLACE INTO master_components (id, name, data_json) VALUES ('comp-lotus-biscoff-soul-cake-spread', 'Lotus Biscoff Soul Cake Spread', '{"id":"comp-lotus-biscoff-soul-cake-spread","name":"Lotus Biscoff Soul Cake Spread","emoji":"🫙","description":"Base Recipe","category":"component","yield":"","servings":1,"time":"","difficulty":"Easy","ingredients":[{"name":"Hot Water","quantity":"75 ml"},{"name":"Normal Water","quantity":"75 ml"},{"name":"Lotus Biscoff Biscuit","quantity":"1 packet"},{"name":"Condensed Milk","quantity":"45 ml"}],"steps":[{"ingredient":"","quantity":"","placement":"","action":"Take hot water and normal water in the grinding pot.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add lotus biscoff biscuits in it.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add the condesned milk.","duration":""}]}');
INSERT OR REPLACE INTO master_components (id, name, data_json) VALUES ('comp-new-york-cheesecake', 'New York Cheesecake', '{"id":"comp-new-york-cheesecake","name":"New York Cheesecake","emoji":"🍰","description":"Base Recipe","category":"component","yield":"","servings":1,"time":"","difficulty":"Easy","ingredients":[{"name":"Cream Cheese","quantity":"500 gm"},{"name":"Milkmaid","quantity":"220 gm"},{"name":"Fresh Cream","quantity":"200 gm"},{"name":"Maida","quantity":"20 gm"},{"name":"Corn Flour","quantity":"20 gm"},{"name":"Vanilla Essence","quantity":"5 gm"},{"name":"Biscuits","quantity":"8 pieces"}],"steps":[{"ingredient":"","quantity":"","placement":"","action":"Break 7 to 8 biscuits.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Crush the biscuits using grinder.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Take the crushed biscuits in a container.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add melted butter to the biscuits.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Mix them well.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Take it in a plate and microwave it for 30sec.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Greece the baking tin with butter and put butter paper.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Line the tin base with biscuit crumbs evenly.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Keep the baking tin in the display fridge.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Take a weighing scale.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add the cream cheese to the plate.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Warm the cream cheese in microwave to make it soft for 30 sec. If required warm it again until soft.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add milkmaid.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add fresh cream.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add the maida.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add the corn flour.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add the Vanilla essence.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Whisk it thoroughly till we get desired consistency. Approx 7-10 mins.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Greece the tin with butter and apply butter paper to it.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Take out the baking tin from the display fridge.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add the batter on top of biscuit crumbs layer and level it. Tap the tin to remove air bubbles.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Take water in a tray and put baking tin in it.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Bake for 35 min at 230 degree in OTG.","duration":""}]}');
INSERT OR REPLACE INTO master_components (id, name, data_json) VALUES ('comp-burnt-basque-cheesecake', 'Burnt Basque Cheesecake', '{"id":"comp-burnt-basque-cheesecake","name":"Burnt Basque Cheesecake","emoji":"🍰","description":"Base Recipe","category":"component","yield":"1200 gm","servings":1,"time":"","difficulty":"Easy","ingredients":[{"name":"Cream Cheese","quantity":"500 gm"},{"name":"Milkmaid","quantity":"150 gm"},{"name":"Curd / Yogurt","quantity":"60 gm"},{"name":"Fresh Cream","quantity":"200 gm"},{"name":"Maida","quantity":"20 gm"},{"name":"Corn Flour","quantity":"20 gm"},{"name":"Vanilla Essence","quantity":"5 gm"}],"steps":[{"ingredient":"","quantity":"","placement":"","action":"Take a weighing scale.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Take a ceramic plate.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Take cream cheese and warm it up for 30 sec.Repeat 30 seconds until its soft like butter.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Put the cream cheese in a mixing bowl.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add milkmaid.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add the Fresh cream.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add the maida.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add the corn flour.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Add the Vanilla essence.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Whisk it thoroughly till we get desired consistency. Approx 7-10 mins.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Greece the tin with butter aqnd apply butter paper to it.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Put the bater in the tin and place the tin in the otg.","duration":""},{"ingredient":"","quantity":"","placement":"","action":"Bake for 35 min at 230 degree in OTG.","duration":""}]}');
